    // Each spider starts at a cell and moves to one of 5 possible destinations (stay, up, down, left, right) if valid.
    // We want to assign each spider a destination such that the number of distinct destinations is minimized.
    // This is a bipartite matching problem: left side = spiders (cells), right side = cells (destinations).
    // Edge from spider at (i,j) to destination (i',j') if (i',j') is a valid move from (i,j).
    // We want to find the maximum matching, which gives the minimum number of occupied cells.
    // Then empty cells = total - max_matching.

    // Build bipartite graph
    // Left nodes: 0 to total-1 (spiders)
    // Right nodes: 0 to total-1 (cells)

    // Adjacency list for left nodes
    const adj = new Array(total).fill(null).map(() => []);

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < m; j++) {
            const spiderId = i * m + j;
            // Stay
            adj[spiderId].push(i * m + j);
            // Up
            if (i > 0) adj[spiderId].push((i - 1) * m + j);
            // Down
            if (i < n - 1) adj[spiderId].push((i + 1) * m + j);
            // Left
            if (j > 0) adj[spiderId].push(i * m + (j - 1));
            // Right
            if (j < m - 1) adj[spiderId].push(i * m + (j + 1));
        }
    }

    // Hopcroft-Karp or simple DFS-based bipartite matching
    // Since total <= 40, we can use simple DFS-based matching.

    const matchR = new Array(total).fill(-1); // matchR[v] = u, the left node matched to right node v

    function dfs(u, visited) {
        for (const v of adj[u]) {
            if (visited[v]) continue;
            visited[v] = true;
